<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileMiddleNameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileMiddleNameAccessor trait.
 *
 * Covers null default, string/VO assignment via withMiddleName,
 * getMiddleName/middleName accessors, and isMiddleNameChanged with/without original.
 */
class UserProfileMiddleNameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withMiddleName creates a new instance with the MiddleName set
     * from a string value, and getMiddleName returns the primitive string.
     */
    public function testWithMiddleNameFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileMiddleNameAccessorUnitTest();

        // Act
        $result = $holder->withMiddleName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getMiddleName());
    }
    /**
     * Asserts that withmiddleName has access to the value object
     * from a string value, and getMiddleName returns the primitive string.
     */
    public function testWithMiddleNameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileMiddleNameAccessorUnitTest();

        // Act
        $result = $holder->withMiddleName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->middleName()->value());
    }
    public function testChangedMiddleName(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileMiddleNameAccessorUnitTest();
        $original = $holder->withMiddleName('one');
        $same = $holder->withMiddleName('one');
        $modified = $holder->withMiddleName('other');

        // Act
        $unchanged = $holder->isMiddleNameChanged();
        $withSame = $original->isMiddleNameChanged($same);
        $withDiferent = $original->isMiddleNameChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileMiddleNameAccessorUnitTest
{
    use UserProfileMiddleNameAccessor;
}
